import{c as t,Q as a,j as s,m as i}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"/make-requirements-great","description":"","frontmatter":{},"headers":[],"relativePath":"research/tweets/2026-06-10-@nurijanian-289888.md","filePath":"research/tweets/2026-06-10-@nurijanian-289888.md","lastUpdated":1785909234000}'),o={name:"research/tweets/2026-06-10-@nurijanian-289888.md"};function r(n,e,l,h,d,u){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="make-requirements-great" tabindex="-1">/make-requirements-great <a class="header-anchor" href="#make-requirements-great" aria-label="Permalink to &quot;/make-requirements-great&quot;">​</a></h1><p><strong>作者</strong>：George from prodmgmt.world (@nurijanian)<br><strong>發布</strong>：2026-06-10<br><strong>原文</strong>：<a href="https://x.com/nurijanian/status/2064666806267289888" target="_blank" rel="noreferrer">https://x.com/nurijanian/status/2064666806267289888</a><br><strong>類型</strong>：Twitter Article<br><strong>互動</strong>：👁️ 587 views · ❤️ 8 · 🔁 0 · 💬 1</p><hr><h2 id="_5維度評分" tabindex="-1">5維度評分 <a class="header-anchor" href="#_5維度評分" aria-label="Permalink to &quot;5維度評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>洞察密度</td><td>3/5</td><td>三層 altitude 框架有用；weasel word 清單實用；但部分篇幅在推自家產品</td></tr><tr><td>可操作性</td><td>4/5</td><td>Weasel word 清單可直接 copy-paste 使用；altitude 框架立即可套用；GitHub 連結提供</td></tr><tr><td>原創性</td><td>3/5</td><td>Requirements altitude 概念已存在（IEEE 標準等），AI-native 包裝是新角度</td></tr><tr><td>論據品質</td><td>2/5</td><td>純個人經驗，無外部數據，後半段偏向 PM OS 產品推廣</td></tr><tr><td>時效性</td><td>4/5</td><td>PM+AI workflow 2026 直接相關；AI 輔助需求評審是現在進行式</td></tr></tbody></table><p><strong>綜合：3.2 / 5</strong> ⭐⭐⭐</p><hr><h2 id="核心論點摘要" tabindex="-1">核心論點摘要 <a class="header-anchor" href="#核心論點摘要" aria-label="Permalink to &quot;核心論點摘要&quot;">​</a></h2><p>PM 把 PRD 貼進 AI 工具做 review，AI 會自信地要求「錯誤的東西」——這不是 prompt 問題，是 AI 的 helpfulness 本身造成的。作者為此建了一個 Claude Code/Cursor skill：<a href="https://github.com/gnurio/nurijanian-skills" target="_blank" rel="noreferrer">make-requirements-great</a>。</p><h3 id="三層需求-altitude" tabindex="-1">三層需求 Altitude <a class="header-anchor" href="#三層需求-altitude" aria-label="Permalink to &quot;三層需求 Altitude&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Altitude</th><th>描述</th><th>Owner</th></tr></thead><tbody><tr><td>Business/Strategic</td><td>組織想要什麼</td><td>Sponsor</td></tr><tr><td>Stakeholder/User</td><td>使用者需要什麼</td><td>該使用者群組</td></tr><tr><td>Solution/Functional</td><td>系統如何行為</td><td>Delivery team</td></tr></tbody></table><p><strong>關鍵</strong>：AI 預設用 solution-level 標準審查所有層次的需求（因訓練資料多為 delivery team 文件）。Skill 要求 AI 先判斷 altitude，再拒絕對 business-level statement 套用 solution-level 測試。</p><h3 id="ai-的缺陷-填補每個-gap" tabindex="-1">AI 的缺陷：填補每個 Gap <a class="header-anchor" href="#ai-的缺陷-填補每個-gap" aria-label="Permalink to &quot;AI 的缺陷：填補每個 Gap&quot;">​</a></h3><ul><li>缺少 latency target → AI 寫「2 秒內」（聽起來合理但無根據）</li><li>這個「猜測」被當成需求，三個 sprint 後有人依此開發</li><li>修正：AI 應寫 flag「Pending decision: target latency」而非自行填值</li><li>開放問題 → 獨立清單「Decisions to be taken during decomposition」，與 defect log 分開</li></ul><h3 id="weasel-word-掃描-可直接使用" tabindex="-1">Weasel Word 掃描（可直接使用） <a class="header-anchor" href="#weasel-word-掃描-可直接使用" aria-label="Permalink to &quot;Weasel Word 掃描（可直接使用）&quot;">​</a></h3><p>以下詞彙一旦出現即標記，要求「量化或刪除」：</p><blockquote><p>appropriate, suitable, adequate, reasonable, user-friendly, intuitive, efficient, fast, slow, robust, scalable, secure, modern, simple, easy, seamless, flexible, optimised, high-quality, sufficient, normal, typical, standard, as needed, where applicable, if necessary, etc., and/or, may, might, could</p></blockquote><ul><li>40 頁 spec 人工審查：~40 分鐘，仍會漏看</li><li>AI 掃描：~1 分鐘，零遺漏，無疲勞</li></ul><h3 id="句子-vs-目錄品質" tabindex="-1">句子 vs. 目錄品質 <a class="header-anchor" href="#句子-vs-目錄品質" aria-label="Permalink to &quot;句子 vs. 目錄品質&quot;">​</a></h3><p><strong>單條需求（9 項）</strong>：unambiguous, clear, concise, correct, testable, implementation-independent, owned, relevant, feasible</p><p><strong>整體需求集合（9 項）</strong>：unique, cohesive, consistent, conformant, current, modifiable, traceable, categorised, complete</p><blockquote><p>「大家都簽署了需求。他們簽署的是句子，沒有人檢查整個集合。」</p></blockquote><p>200 條需求中若 non-functional requirements 為零 → 不是「乾淨通過」，是遺漏。</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>If you&#39;re a PM who pastes PRDs into Claude or Cursor for review, you know the feeling. The AI demands the wrong things with total confidence. Paste in a business-intent statement and it comes back asking for latency targets. It flags missing detail that was never supposed to be there yet. The review looks thorough, and it points you straight at problems that don&#39;t exist.</p><p>I hit this enough times to realize the problem wasn&#39;t my prompts. The tool is trained to be maximally helpful, and that helpfulness is exactly what wrecks a requirements review.</p><p>So I built a skill to stop it. It lives on GitHub as make-requirements-great, and most of what it does is tell the AI to shut up at the right moments. Building it taught me a handful of things that hold whether you use my skill or write your own.</p><h2 id="requirements-live-at-three-altitudes" tabindex="-1">Requirements live at three altitudes <a class="header-anchor" href="#requirements-live-at-three-altitudes" aria-label="Permalink to &quot;Requirements live at three altitudes&quot;">​</a></h2><p>The fix is a concept the AI doesn&#39;t hold on its own. A requirement has an altitude, and you have to know which one you&#39;re reading before you judge it.</p><p>There are three of them. A business or strategic requirement describes what the organization wants, and the sponsor owns it. A stakeholder or user requirement describes what a group of users needs, and that group owns it. A solution or functional requirement describes how the system behaves, and the delivery team owns it.</p><p>A high-level requirement is a deliberate artifact with its own job, not a low-level one someone forgot to finish. &quot;Update preferences from any surface&quot; does its job perfectly as a business statement. Grade it against solution-level criteria and you&#39;ve made a category error.</p><p>This is one of the most common ways a requirements review goes wrong. AI does it by default on every line, because most of its training comes from delivery-team documentation. So the skill starts by asking which altitude a requirement was written at. Then it refuses to apply solution-level tests to a business-level statement. That one instruction goes most of the way to stopping the AI from demanding latencies.</p><h2 id="the-thing-ai-does-a-lot-fills-every-gap" tabindex="-1">The thing AI does a lot: fills every gap <a class="header-anchor" href="#the-thing-ai-does-a-lot-fills-every-gap" aria-label="Permalink to &quot;The thing AI does a lot: fills every gap&quot;">​</a></h2><p>When a requirement is missing detail, AI invents it.</p><p>Ask it to shape requirements from a messy thread of notes and it hands you a complete-looking document, where &quot;complete&quot; includes decisions nobody made. If the stakeholder hasn&#39;t set a latency target, the AI writes &quot;within 2 seconds&quot; because two seconds sounds plausible. Now you have a guess presented as a requirement, and three sprints later someone builds to it as if it were real.</p><p>The skill treats that helpfulness as a defect. When a stakeholder hasn&#39;t decided, the AI should write a flag rather than a plausible value: &quot;Pending decision: target latency.&quot; At high altitudes, missing detail isn&#39;t a defect at all. It goes on a separate list called &quot;Decisions to be taken during decomposition.&quot; That list sits apart from the defect log, so nobody confuses an open question with a mistake.</p><p>The open question tells you where a real human still needs to decide something. A confident guess buries that decision point in the backlog, unmarked, where it surfaces as a surprise during the build. Getting AI to leave gaps open instead of papering over them is half the work.</p><h2 id="the-weasel-word-scan-and-the-minute-it-saves" tabindex="-1">The weasel word scan, and the minute it saves <a class="header-anchor" href="#the-weasel-word-scan-and-the-minute-it-saves" aria-label="Permalink to &quot;The weasel word scan, and the minute it saves&quot;">​</a></h2><p>This next part you can copy and use today.</p><p>Before any deeper analysis, the skill runs a literal scan for weasel words. These words feel like requirements but commit to nothing. They pass review, then explode during build when two people interpret them differently.</p><p>Here is the list it scans for:</p><p>appropriate, suitable, adequate, reasonable, user-friendly, intuitive, efficient, fast, slow, robust, scalable, secure, modern, simple, easy, seamless, flexible, optimised, high-quality, sufficient, normal, typical, standard, as needed, where applicable, if necessary, etc., and/or, may, might, could.</p><p>Each hit is a flag, not an automatic fail. The instruction is the same every time: quantify it or remove it. &quot;Handle preferences appropriately&quot; becomes &quot;propagate preference changes to all surfaces within 5 seconds,&quot; or it goes.</p><p>This one move takes requirements review from &quot;I&#39;ll know it when I see it&quot; to something close to a grep. A human reviewer reading a 40-page spec for ambiguity spends most of an hour. They still miss half the hits, because attention fades. Run the scan and you get a defect log in about a minute, every word caught, no fatigue. What took 40 minutes to hunt now takes 1.</p><h2 id="sentences-pass-catalogues-fail" tabindex="-1">Sentences pass. Catalogues fail. <a class="header-anchor" href="#sentences-pass-catalogues-fail" aria-label="Permalink to &quot;Sentences pass. Catalogues fail.&quot;">​</a></h2><p>The deepest lesson took me longest to see. The 18 quality characteristics in the skill split into two groups.</p><p>Nine apply to one requirement at a time: unambiguous, clear, concise, correct, testable, implementation-independent, owned, relevant, feasible. A human reviewer can hold these in their head while reading line by line.</p><p>The other nine only make sense across the whole set: unique, cohesive, consistent, conformant, current, modifiable, traceable, categorised, complete. These are where real products break. Forty individually well-formed requirements can still contradict each other, drift in terminology halfway through, or miss an entire category like security or performance. No human reads 40 requirements and holds all of them in working memory at once. AI does, and it runs both passes at the same time.</p><p>You know the &quot;but everyone signed off on the requirements.&quot; They signed off on the sentences. Nobody checked the set. A catalogue of 200 requirements with zero non-functional requirements isn&#39;t a clean bill of health. It&#39;s an omission.</p><h2 id="how-to-get-it" tabindex="-1">How to get it <a class="header-anchor" href="#how-to-get-it" aria-label="Permalink to &quot;How to get it&quot;">​</a></h2><p>You can do this yourself. The skill is open on GitHub: <a href="https://github.com/gnurio/nurijanian-skills" target="_blank" rel="noreferrer">https://github.com/gnurio/nurijanian-skills</a>. It&#39;s free to read, fork, and run in Claude Code or Cursor. Start with the weasel scan on whatever PRD is open in front of you right now. You&#39;ll have a defect log before your coffee&#39;s cold.</p><p>Requirements review is one recurring PM task. You have a dozen others that AI defaults to doing badly for the same reason: it&#39;s helpful, it fills gaps, and it doesn&#39;t know which chair it&#39;s sitting on. Encoding the judgment for each one as a reusable skill takes real effort. Assembling that library by hand is slow.</p><p>That&#39;s what PM OS is: the operating layer where make-requirements-great sits alongside 235 skills and 11 guided workflows. All sitting on top of a memory/context system that self-updates over time.</p><h2 id="you-can-get-pm-os-here" tabindex="-1">You can get PM OS here. <a class="header-anchor" href="#you-can-get-pm-os-here" aria-label="Permalink to &quot;You can get PM OS here.&quot;">​</a></h2><hr><p><em>歸檔時間：2026-06-10</em></p>',57)])])}const m=t(o,[["render",r]]);export{p as __pageData,m as default};
